/** Status dot for polled tasks */
function TaskStatusDot({ status }: { status: PolledTask['status'] }) {
  const colorMap: Record<string, string> = {
    pending: 'bg-gray-400/60',
    running: 'bg-blue-400',
    complete: 'bg-green-400',
