  const [localApprovals, setLocalApprovals] = useState<Map<string, string>>(new Map());
  /** Dismissed task IDs — hide approved/rejected tasks after user action */
  const [dismissedPolledTasks, setDismissedPolledTasks] = useState<Set<string>>(new Set());

  // Poll /api/tasks every 5 seconds
  useEffect(() => {
    let cancelled = false;

    const fetchTasks = async () => {
      try {
        const res = await fetch('/api/tasks');
